python3 - <<'EOF'
from pathlib import Path
import re

def sub(path, old, new, count=1):
    p = Path(path); s = p.read_text()
    assert s.count(old) == count, (path, old[:60], s.count(old))
    p.write_text(s.replace(old, new))

# --- typings for new icons
d = Path("apps/web/src/tabler-icons.d.ts")
extra = "".join(f"""
declare module '@tabler/icons-react/dist/esm/icons/{n}.mjs' {{
  import type {{ {n} }} from '@tabler/icons-react';
  const Icon: typeof {n};
  export default Icon;
}}
""" for n in ["IconSparkles","IconMicrophone","IconSend2","IconVolume","IconVolumeOff","IconMessageChatbot"])
d.write_text(d.read_text().rstrip("\n") + "\n" + extra)

# --- viewport: smooth orbit by degrees
v = "apps/web/src/components/AssemblyViewport.tsx"
